        You will be given the root cause of a bug, the commit message and the corresponding patch.
        You need to extract all code statements that lead to the bug from the patch, based on the root cause and the commit message.

        Root cause:
        The bug arises from the NFS server failing to apply the user's umask when creating new objects on filesystems that lack ACL (Access Control List) support. In such filesystems, it is the responsibility of the caller, rather than the filesystem itself, to properly handle the umask. The absence of checks to apply the current umask in the code results in the incorrect permission bits being set for newly created files and directories.

        Commit message:
        nfsd: apply umask on fs without ACL support

The server is failing to apply the umask when creating new objects on
filesystems without ACL support.

To reproduce this, you need to use NFSv4.2 and a client and server
recent enough to support umask, and you need to export a filesystem that
lacks ACL support (for example, ext4 with the "noacl" mount option).

Filesystems with ACL support are expected to take care of the umask
themselves (usually by calling posix_acl_create).

For filesystems without ACL support, this is up to the caller of
vfs_create(), vfs_mknod(), or vfs_mkdir().

Reported-by: Elliott Mitchell <ehem+debian@m5p.com>
Reported-by: Salvatore Bonaccorso <carnil@debian.org>
Tested-by: Salvatore Bonaccorso <carnil@debian.org>
Fixes: 47057abde515 ("nfsd: add support for the umask attribute")
Cc: stable@vger.kernel.org
Signed-off-by: J. Bruce Fields <bfields@redhat.com>  

        Patch:
         /* The parent directory should already be locked: */
 __be32
 nfsd_create_locked(struct svc_rqst *rqstp, struct svc_fh *fhp,
 		char *fname, int flen, struct iattr *iap,
 		int type, dev_t rdev, struct svc_fh *resfhp)
 {
 	struct dentry	*dentry, *dchild;
 	struct inode	*dirp;
 	__be32		err;
 	__be32		err2;
 	int		host_err;

 	dentry = fhp->fh_dentry;
 	dirp = d_inode(dentry);

 	dchild = dget(resfhp->fh_dentry);
 	if (!fhp->fh_locked) {
 		WARN_ONCE(1, "nfsd_create: parent %pd2 not locked!\n",
 				dentry);
 		err = nfserr_io;
 		goto out;
 	}

 	err = nfsd_permission(rqstp, fhp->fh_export, dentry, NFSD_MAY_CREATE);
 	if (err)
 		goto out;

 	if (!(iap->ia_valid & ATTR_MODE))
 		iap->ia_mode = 0;
 	iap->ia_mode = (iap->ia_mode & S_IALLUGO) | type;

+	if (!IS_POSIXACL(dirp))
+		iap->ia_mode &= ~current_umask();
+
 	err = 0;
 	host_err = 0;
 	switch (type) {
 	case S_IFREG:
 		host_err = vfs_create(dirp, dchild, iap->ia_mode, true);
 		if (!host_err)
 			nfsd_check_ignore_resizing(iap);
 		break;
 	case S_IFDIR:
 		host_err = vfs_mkdir(dirp, dchild, iap->ia_mode);
 		if (!host_err && unlikely(d_unhashed(dchild))) {
 			struct dentry *d;
 			d = lookup_one_len(dchild->d_name.name,
 					   dchild->d_parent,
 					   dchild->d_name.len);
 			if (IS_ERR(d)) {
 				host_err = PTR_ERR(d);
 				break;
 			}
 			if (unlikely(d_is_negative(d))) {
 				dput(d);
 				err = nfserr_serverfault;
 				goto out;
 			}
 			dput(resfhp->fh_dentry);
 			resfhp->fh_dentry = dget(d);
 			err = fh_update(resfhp);
 			dput(dchild);
 			dchild = d;
 			if (err)
 				goto out;
 		}
 		break;
 	case S_IFCHR:
 	case S_IFBLK:
 	case S_IFIFO:
 	case S_IFSOCK:
 		host_err = vfs_mknod(dirp, dchild, iap->ia_mode, rdev);
 		break;
 	default:
 		printk(KERN_WARNING "nfsd: bad file type %o in nfsd_create\n",
 		       type);
 		host_err = -EINVAL;
 	}
 	if (host_err < 0)
 		goto out_nfserr;

 	err = nfsd_create_setattr(rqstp, resfhp, iap);

 	/*
 	 * nfsd_create_setattr already committed the child.  Transactional
 	 * filesystems had a chance to commit changes for both parent and
 	 * child simultaneously making the following commit_metadata a
 	 * noop.
 	 */
 	err2 = nfserrno(commit_metadata(fhp));
 	if (err2)
 		err = err2;
 	/*
 	 * Update the file handle to get the new inode info.
 	 */
 	if (!err)
 		err = fh_update(resfhp);
 out:
 	dput(dchild);
 	return err;

 out_nfserr:
 	err = nfserrno(host_err);
 	goto out;
 }

  */
 __be32
 do_nfsd_create(struct svc_rqst *rqstp, struct svc_fh *fhp,
 		char *fname, int flen, struct iattr *iap,
 		struct svc_fh *resfhp, int createmode, u32 *verifier,
 	        bool *truncp, bool *created)
 {
 	struct dentry	*dentry, *dchild = NULL;
 	struct inode	*dirp;
 	__be32		err;
 	int		host_err;
 	__u32		v_mtime=0, v_atime=0;

 	err = nfserr_perm;
 	if (!flen)
 		goto out;
 	err = nfserr_exist;
 	if (isdotent(fname, flen))
 		goto out;
 	if (!(iap->ia_valid & ATTR_MODE))
 		iap->ia_mode = 0;
 	err = fh_verify(rqstp, fhp, S_IFDIR, NFSD_MAY_EXEC);
 	if (err)
 		goto out;

 	dentry = fhp->fh_dentry;
 	dirp = d_inode(dentry);

 	host_err = fh_want_write(fhp);
 	if (host_err)
 		goto out_nfserr;

 	fh_lock_nested(fhp, I_MUTEX_PARENT);

 	/*
 	 * Compose the response file handle.
 	 */
 	dchild = lookup_one_len(fname, dentry, flen);
 	host_err = PTR_ERR(dchild);
 	if (IS_ERR(dchild))
 		goto out_nfserr;

 	/* If file doesn't exist, check for permissions to create one */
 	if (d_really_is_negative(dchild)) {
 		err = fh_verify(rqstp, fhp, S_IFDIR, NFSD_MAY_CREATE);
 		if (err)
 			goto out;
 	}

 	err = fh_compose(resfhp, fhp->fh_export, dchild, fhp);
 	if (err)
 		goto out;

 	if (nfsd_create_is_exclusive(createmode)) {
 		/* solaris7 gets confused (bugid 4218508) if these have
 		 * the high bit set, so just clear the high bits. If this is
 		 * ever changed to use different attrs for storing the
 		 * verifier, then do_open_lookup() will also need to be fixed
 		 * accordingly.
 		 */
 		v_mtime = verifier[0]&0x7fffffff;
 		v_atime = verifier[1]&0x7fffffff;
 	}

 	if (d_really_is_positive(dchild)) {
 		err = 0;

 		switch (createmode) {
 		case NFS3_CREATE_UNCHECKED:
 			if (! d_is_reg(dchild))
 				goto out;
 			else if (truncp) {
 				/* in nfsv4, we need to treat this case a little
 				 * differently.  we don't want to truncate the
 				 * file now; this would be wrong if the OPEN
 				 * fails for some other reason.  furthermore,
 				 * if the size is nonzero, we should ignore it
 				 * according to spec!
 				 */
 				*truncp = (iap->ia_valid & ATTR_SIZE) && !iap->ia_size;
 			}
 			else {
 				iap->ia_valid &= ATTR_SIZE;
 				goto set_attr;
 			}
 			break;
 		case NFS3_CREATE_EXCLUSIVE:
 			if (   d_inode(dchild)->i_mtime.tv_sec == v_mtime
 			    && d_inode(dchild)->i_atime.tv_sec == v_atime
 			    && d_inode(dchild)->i_size  == 0 ) {
 				if (created)
 					*created = true;
 				break;
 			}
 			/* fall through */
 		case NFS4_CREATE_EXCLUSIVE4_1:
 			if (   d_inode(dchild)->i_mtime.tv_sec == v_mtime
 			    && d_inode(dchild)->i_atime.tv_sec == v_atime
 			    && d_inode(dchild)->i_size  == 0 ) {
 				if (created)
 					*created = true;
 				goto set_attr;
 			}
 			/* fall through */
 		case NFS3_CREATE_GUARDED:
 			err = nfserr_exist;
 		}
 		fh_drop_write(fhp);
 		goto out;
 	}

+	if (!IS_POSIXACL(dirp))
+		iap->ia_mode &= ~current_umask();
+
 	host_err = vfs_create(dirp, dchild, iap->ia_mode, true);
 	if (host_err < 0) {
 		fh_drop_write(fhp);
 		goto out_nfserr;
 	}
 	if (created)
 		*created = true;

 	nfsd_check_ignore_resizing(iap);

 	if (nfsd_create_is_exclusive(createmode)) {
 		/* Cram the verifier into atime/mtime */
 		iap->ia_valid = ATTR_MTIME|ATTR_ATIME
 			| ATTR_MTIME_SET|ATTR_ATIME_SET;
 		/* XXX someone who knows this better please fix it for nsec */ 
 		iap->ia_mtime.tv_sec = v_mtime;
 		iap->ia_atime.tv_sec = v_atime;
 		iap->ia_mtime.tv_nsec = 0;
 		iap->ia_atime.tv_nsec = 0;
 	}

  set_attr:
 	err = nfsd_create_setattr(rqstp, resfhp, iap);

 	/*
 	 * nfsd_create_setattr already committed the child
 	 * (and possibly also the parent).
 	 */
 	if (!err)
 		err = nfserrno(commit_metadata(fhp));

 	/*
 	 * Update the filehandle to get the new inode info.
 	 */
 	if (!err)
 		err = fh_update(resfhp);

  out:
 	fh_unlock(fhp);
 	if (dchild && !IS_ERR(dchild))
 		dput(dchild);
 	fh_drop_write(fhp);
  	return err;

  out_nfserr:
 	err = nfserrno(host_err);
 	goto out;
 }
 #endif /* CONFIG_NFSD_V3 */


